from datetime import datetime
from collections import defaultdict

def detect(events, threshold=5, window_seconds=600):
    grouped = defaultdict(list)
    for e in events:
        if e.get("outcome") == "failure":
            key = (e["user"], e["src_ip"])
            grouped[key].append(datetime.fromisoformat(e["timestamp"].replace("Z","+00:00")))
    alerts = []
    for key, times in grouped.items():
        times.sort()
        left = 0
        for right, current in enumerate(times):
            while (current - times[left]).total_seconds() > window_seconds:
                left += 1
            if right - left + 1 >= threshold:
                alerts.append({"user": key[0], "src_ip": key[1], "count": right-left+1})
                break
    return alerts

