from datetime import datetime

def detect(events, threshold=5, window_seconds=600):
    times = []
    for e in events:
        if e.get("outcome") != "failure" or "timestamp" not in e:
            continue
        try:
            times.append(datetime.fromisoformat(e["timestamp"].replace("Z","+00:00")))
        except ValueError:
            continue
    times.sort()
    for right, current in enumerate(times):
        left = right
        while left > 0 and (current-times[left-1]).total_seconds() <= window_seconds:
            left -= 1
        if right-left+1 >= threshold:
            return True
    return False

