# Detection Engineering Fundamentals capstone
# File: detector.py
import argparse, json, math
from collections import Counter, defaultdict
from datetime import datetime, timezone

def parse_time(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00"))

def load_events(path):
    with open(path, encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, list):
        raise ValueError("events.json must contain a JSON array")
    return data

def validate_event(e):
    required = {"timestamp", "event_type", "user", "src_ip"}
    missing = required - e.keys()
    return not missing, sorted(missing)

def detect_bruteforce(events, threshold=5, window_minutes=10):
    buckets = defaultdict(list)
    for e in events:
        if e.get("event_type") != "authentication_failure":
            continue
        try:
            ts = parse_time(e["timestamp"])
        except (KeyError, ValueError):
            continue
        key = (e.get("user"), e.get("src_ip"))
        buckets[key].append(ts)
    alerts = []
    window = window_minutes * 60
    for key, times in buckets.items():
        times.sort()
        left = 0
        for right in range(len(times)):
            while (times[right] - times[left]).total_seconds() > window:
                left += 1
            if right - left + 1 >= threshold:
                alerts.append({
                    "rule_id": "AUTH-001",
                    "user": key[0], "src_ip": key[1],
                    "count": right-left+1,
                    "first_seen": times[left].isoformat(),
                    "last_seen": times[right].isoformat()
                })
                break
    return alerts

def detect_new_admin(events):
    alerts = []
    for e in events:
        if e.get("event_type") == "role_assignment" and e.get("role") == "admin":
            alerts.append({
                "rule_id":"IAM-001",
                "user":e.get("user"),
                "role":e.get("role"),
                "timestamp":e.get("timestamp"),
                "src_ip":e.get("src_ip")
            })
    return alerts

def score(alert):
    score = 0
    if alert["rule_id"] == "AUTH-001": score += min(alert["count"] * 10, 50)
    if alert["rule_id"] == "IAM-001": score += 40
    if alert.get("src_ip", "").startswith("203.0.113."): score += 10
    return min(score, 100)

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("events")
    ap.add_argument("-o", "--output", default="detection_report.json")
    args = ap.parse_args()
    events = load_events(args.events)
    valid = []
    invalid = []
    for e in events:
        ok, missing = validate_event(e)
        (valid if ok else invalid).append({"event":e, "missing":missing})
    alerts = detect_bruteforce([x["event"] for x in valid])
    alerts += detect_new_admin([x["event"] for x in valid])
    for a in alerts: a["risk_score"] = score(a)
    report = {
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "events_total": len(events),
        "events_invalid": len(invalid),
        "alerts": alerts,
        "quality": {
            "coverage": ["authentication_failure", "role_assignment"],
            "invalid_event_examples": invalid[:3]
        }
    }
    with open(args.output, "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2)
    print(f"wrote {args.output} with {len(alerts)} alerts")

if __name__ == "__main__":
    main()
